package studio.jiayu.neoagent;
import android.app.Activity;import android.os.*;import android.widget.*;import android.graphics.Rect;import android.view.accessibility.AccessibilityNodeInfo;import java.io.*;import java.util.*;import org.json.*;
/** Real native nested controls, without merchant UI or network access. */
final class NativeLabelsContracts {
 static void start(Activity a){LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(30,140,30,30);a.setContentView(root);LinearLayout search=new LinearLayout(a);search.setClickable(true);root.addView(search);TextView title=new TextView(a);title.setText("搜索百洁布");search.addView(title);EditText input=new EditText(a);input.setText("本地查询");search.addView(input);Button clear=new Button(a);clear.setText("删除");search.addView(clear);LinearLayout submit=new LinearLayout(a);submit.setClickable(true);root.addView(submit);TextView finalText=new TextView(a);finalText.setText("提交订单");submit.addView(finalText);LinearLayout outer=new LinearLayout(a);outer.setClickable(true);root.addView(outer);TextView caption=new TextView(a);caption.setText("订单工具区");outer.addView(caption);Button pay=new Button(a);pay.setText("立即支付");outer.addView(pay);new Handler().postDelayed(()->run(a),900);}
 static void yes(boolean b,String m)throws Exception{if(!b)throw new Exception(m);}
 static AccessibilityNodeInfo node(AccessibilityNodeInfo root,String text)throws Exception{for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(text.contentEquals(n.getText()))return n;throw new Exception("Missing owned fixture node");}
 static void run(Activity a){JSONObject r=new JSONObject();int n=0;try{ControlService s=ControlService.instance;yes(s!=null&&s.connected&&!s.busy(),"Runtime not idle");AccessibilityNodeInfo root=s.getRootInActiveWindow();yes(root!=null&&a.getPackageName().contentEquals(root.getPackageName()),"Fixture not foreground");n++;String search=NativeLabels.label(node(root,"搜索百洁布").getParent());yes(search.contains("搜索百洁布")&&!search.contains("删除")&&!search.contains("本地查询"),"Independent descendant leaked into search label");n++;yes(!ActionGuard.requiresHandoff(search,true),"Search wrapper blocked");n++;yes(ActionGuard.requiresHandoff(NativeLabels.label(node(root,"删除")),true),"Actual delete control lost guard");n++;String submit=NativeLabels.label(node(root,"提交订单").getParent());yes(submit.contains("提交订单")&&ActionGuard.finalAction(submit),"Noninteractive final label lost");n++;String outer=NativeLabels.label(node(root,"订单工具区").getParent());yes(!outer.contains("立即支付"),"Independent payment child leaked into wrapper");n++;yes(ActionGuard.finalAction(NativeLabels.label(node(root,"立即支付"))),"Actual payment child lost guard");n++;ArrayList<Rect> forbidden=new ArrayList<>();s.collectForbidden(root,forbidden,0);Rect pay=new Rect();node(root,"立即支付").getBoundsInScreen(pay);yes(forbidden.contains(pay),"Payment child missing path boundary");n++;r.put("success",true);}catch(Exception e){try{r.put("success",false).put("failure",e.getMessage());}catch(Exception ignored){}}try(FileOutputStream out=a.openFileOutput("native-labels-contracts.json",0)){out.write(r.put("passed",n).put("real_network_calls",0).put("third_party_actions",0).toString(2).getBytes("UTF-8"));}catch(Exception ignored){}a.finish();}
}
